/**
 * ============================================================================
 * CO₂ EMISSION PREDICTOR
 * ============================================================================
 *
 * Type definitions for communication between the React frontend and the
 * FastAPI machine-learning backend.
 *
 * Architecture:
 *
 * React
 *   ↓
 * TypeScript API Types
 *   ↓
 * FastAPI
 *   ↓
 * Machine-Learning Service
 *   ↓
 * Trained Model + Dataset
 *
 * IMPORTANT
 * ---------
 * Model metrics, dataset statistics, model metadata, and evaluation
 * information are generated by the backend.
 *
 * The frontend must NEVER hardcode model performance values or dataset
 * statistics.
 * ============================================================================
 */


/* ============================================================================
   API / ROOT RESPONSE
============================================================================ */

/**
 * Response returned by:
 *
 * GET /
 */
export interface ApiWelcomeResponse {
  message: string;

  version: string;

  documentation: string;

  alternative_documentation: string;

  health: string;

  model: string;

  prediction_endpoint: string;
}


/* ============================================================================
   HEALTH
============================================================================ */

/**
 * Response returned by:
 *
 * GET /api/health
 */
export interface HealthResponse {
  status: string;

  service: string;
}


/* ============================================================================
   PREDICTION REQUEST
============================================================================ */

/**
 * Request payload sent to:
 *
 * POST /api/predict
 *
 * IMPORTANT
 * ---------
 * The property names must exactly match the FastAPI
 * PredictionRequest schema.
 */
export interface PredictionRequest {
  /**
   * Vehicle engine size.
   *
   * Unit depends on the trained model.
   */
  engine_size: number;

  /**
   * Combined fuel consumption value used by the model.
   */
  fuel_consumption_mpg: number;
}


/* ============================================================================
   PREDICTION RESPONSE
============================================================================ */

/**
 * Response returned by:
 *
 * POST /api/predict
 */
export interface PredictionResponse {
  /**
   * Predicted CO₂ emissions.
   */
  predicted_co2: number;

  /**
   * Engine size supplied to the model.
   */
  engine_size: number;

  /**
   * Fuel consumption supplied to the model.
   */
  fuel_consumption_mpg: number;

  /**
   * Optional display unit returned by the backend.
   *
   * Example:
   * "g/km"
   */
  unit?: string;
}


/* ============================================================================
   MODEL METRICS
============================================================================ */

/**
 * Machine-learning evaluation metrics.
 *
 * These values must come from the backend.
 */
export interface ModelMetrics {
  /**
   * Coefficient of determination.
   *
   * Higher values generally indicate better explanatory performance.
   */
  r2_score: number | null;

  /**
   * Mean Absolute Error.
   */
  mae: number | null;

  /**
   * Mean Squared Error.
   *
   * Optional because the API may not expose it.
   */
  mse?: number | null;

  /**
   * Root Mean Squared Error.
   */
  rmse: number | null;
}


/* ============================================================================
   FEATURE STATISTICS
============================================================================ */

/**
 * Statistical information for an individual dataset feature.
 */
export interface FeatureStatistics {
  /**
   * Minimum observed value.
   */
  min: number | null;

  /**
   * Maximum observed value.
   */
  max: number | null;

  /**
   * Mean value.
   */
  mean: number | null;

  /**
   * Median value.
   */
  median: number | null;

  /**
   * Standard deviation.
   */
  std: number | null;
}


/* ============================================================================
   TARGET STATISTICS
============================================================================ */

/**
 * Statistical information for the prediction target.
 */
export interface TargetStatistics {
  /**
   * Dataset column containing the target.
   */
  column: string;

  /**
   * Minimum target value.
   */
  min: number | null;

  /**
   * Maximum target value.
   */
  max: number | null;

  /**
   * Mean target value.
   */
  mean: number | null;

  /**
   * Median target value.
   */
  median: number | null;

  /**
   * Standard deviation of the target.
   */
  std: number | null;
}


/* ============================================================================
   DATASET STATISTICS
============================================================================ */

/**
 * Statistics calculated from the actual training dataset.
 *
 * IMPORTANT
 * ---------
 * These values are generated by the backend.
 *
 * They should NEVER be manually entered into the React application.
 */
export interface DatasetStatistics {
  /**
   * Number of records in the dataset.
   */
  records: number | null;

  /**
   * Number of model input features.
   */
  feature_count: number | null;

  /**
   * Names of the dataset/model features.
   */
  features: string[];

  /**
   * Name of the prediction target.
   */
  target: string;

  /**
   * Minimum engine size in the dataset.
   */
  engine_size_min: number | null;

  /**
   * Maximum engine size in the dataset.
   */
  engine_size_max: number | null;

  /**
   * Minimum combined fuel consumption value.
   */
  fuel_consumption_mpg_min: number | null;

  /**
   * Maximum combined fuel consumption value.
   */
  fuel_consumption_mpg_max: number | null;

  /**
   * Minimum CO₂ emission value.
   */
  co2_min: number | null;

  /**
   * Maximum CO₂ emission value.
   */
  co2_max: number | null;

  /**
   * Detailed statistics for every feature.
   *
   * This is optional so the frontend remains compatible with APIs
   * that only return aggregate dataset information.
   */
  feature_statistics?: Record<
    string,
    FeatureStatistics
  >;

  /**
   * Detailed statistics for the prediction target.
   */
  target_statistics?: TargetStatistics;
}


/* ============================================================================
   MODEL EVALUATION INFORMATION
============================================================================ */

/**
 * Information about how the model was evaluated.
 */
export interface ModelEvaluation {
  /**
   * Number of samples used for training.
   */
  training_samples: number | null;

  /**
   * Number of samples used for testing/evaluation.
   */
  testing_samples: number | null;

  /**
   * Total number of samples used during model preparation.
   */
  total_samples: number | null;

  /**
   * Number of input features.
   */
  feature_count: number | null;

  /**
   * Test split ratio.
   *
   * Example:
   * 0.2
   */
  test_size: number | null;

  /**
   * Random state used during train/test splitting.
   */
  random_state: number | null;
}


/* ============================================================================
   MODEL ARTIFACT INFORMATION
============================================================================ */

/**
 * Information about persisted model files.
 *
 * These are informational values only.
 *
 * The frontend should never attempt to access local model files directly.
 */
export interface ModelArtifacts {
  /**
   * Name or relative identifier of the trained model file.
   */
  model_file: string;

  /**
   * Name or relative identifier of the scaler file.
   */
  scaler_file: string;
}


/* ============================================================================
   MODEL INFORMATION RESPONSE
============================================================================ */

/**
 * Complete response returned by:
 *
 * GET /api/model
 *
 * This is the primary contract consumed by ModelPage.tsx.
 */
export interface ModelInfoResponse {
  /**
   * Human-readable model name.
   */
  model_name: string;

  /**
   * Machine-learning algorithm used by the model.
   */
  algorithm: string;

  /**
   * Model version.
   */
  version: string;

  /**
   * Input features used by the trained model.
   */
  features: string[];

  /**
   * Prediction target.
   */
  target: string;

  /**
   * Unit of the prediction target.
   *
   * Example:
   * "g/km"
   */
  target_unit: string;

  /**
   * Model evaluation metrics.
   */
  metrics: ModelMetrics | null;

  /**
   * Evaluation/training information.
   */
  evaluation?: ModelEvaluation | null;

  /**
   * Dataset statistics.
   */
  dataset: DatasetStatistics | null;

  /**
   * Persisted model artifact information.
   */
  artifacts?: ModelArtifacts | null;
}


/* ============================================================================
   API ERROR
============================================================================ */

/**
 * Standard error response returned by FastAPI.
 *
 * FastAPI validation errors may also contain a `detail` array/object,
 * therefore `detail` intentionally accepts unknown.
 */
export interface ApiErrorResponse {
  detail: unknown;
}


/* ============================================================================
   API RESULT HELPERS
============================================================================ */

/**
 * Generic API response wrapper.
 *
 * Useful for service-layer functions when you want to explicitly represent
 * successful and failed API calls.
 */
export interface ApiResult<T> {
  data: T | null;

  error: string | null;

  success: boolean;
}


/* ============================================================================
   TYPE GUARDS
============================================================================ */

/**
 * Runtime check for numeric API values.
 */
export function isFiniteNumber(
  value: unknown,
): value is number {
  return (
    typeof value === "number" &&
    Number.isFinite(value)
  );
}


/**
 * Runtime check for non-empty strings.
 */
export function isNonEmptyString(
  value: unknown,
): value is string {
  return (
    typeof value === "string" &&
    value.trim().length > 0
  );
}